        if t - T0 < FWD_S:
            return (0.0, 0.8, -41.0)
        PHASE = 'rev'
    steer = 1.5 * h + 5.0
    steer = max(-42.0, min(42.0, steer))
    return (steer, -1.0, -41.0)

